<?php

namespace Firebird\Tests;

use Firebird\FirebirdConnection;
use Illuminate\Database\Schema\Blueprint;
use PHPUnit\Framework\TestCase as BaseTestCase;

/**
 * SQL generated by the Megabit additions to the schema grammar. No database:
 * the connection is never opened.
 */
class SchemaGrammarTest extends BaseTestCase
{
    private function sql(string $table, callable $definition): array
    {
        $connection = new FirebirdConnection(fn () => throw new \LogicException('no database in this test'), '', '', ['driver' => 'firebird']);
        $connection->useDefaultSchemaGrammar();

        return (new Blueprint($connection, $table, $definition))->toSql();
    }

    public function test_increments_becomes_identity(): void
    {
        // Laravel's own "migrations" table.
        $sql = $this->sql('migrations', function (Blueprint $t) {
            $t->create();
            $t->increments('id');
            $t->string('migration');
            $t->integer('batch');
        });

        $this->assertStringContainsString('"id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL', $sql[0]);
    }

    public function test_named_primary_key_and_index(): void
    {
        $sql = $this->sql('RUC_SET', function (Blueprint $t) {
            $t->create();
            $t->string('RUC', 20);
            $t->integer('DV');
            $t->primary(['RUC', 'DV'], 'RUC_SET_PRI_KEY');
            $t->index('RUCDV', 'RUC_SET_IDX');
        });

        $this->assertSame('ALTER TABLE "RUC_SET" ADD CONSTRAINT "RUC_SET_PRI_KEY" PRIMARY KEY ("RUC", "DV")', $sql[1]);
        $this->assertSame('CREATE INDEX "RUC_SET_IDX" ON "RUC_SET" ("RUCDV")', $sql[2]);
    }

    public function test_add_and_drop_column_and_drop_index(): void
    {
        $this->assertSame(['ALTER TABLE "RUC_SET" ADD "PORTE" VARCHAR(10)'],
            $this->sql('RUC_SET', fn (Blueprint $t) => $t->string('PORTE', 10)->nullable()));
        $this->assertSame(['ALTER TABLE "RUC_SET" DROP "PORTE", DROP "INFO"'],
            $this->sql('RUC_SET', fn (Blueprint $t) => $t->dropColumn(['PORTE', 'INFO'])));
        $this->assertSame(['DROP INDEX "RUC_SET_IDX"'],
            $this->sql('RUC_SET', fn (Blueprint $t) => $t->dropIndex('RUC_SET_IDX')));
    }

    public function test_names_are_cut_to_31_characters(): void
    {
        $sql = $this->sql('RUC_SET', fn (Blueprint $t) => $t->index('NOME', str_repeat('X', 40)));

        $this->assertSame('CREATE INDEX "'.str_repeat('X', 31).'" ON "RUC_SET" ("NOME")', $sql[0]);
    }
}
